import { z } from 'zod'
import { uuidSchema } from './common.js'

export const registerInstallationSchema = z
  .object({
    installationId: uuidSchema,
    secret: z
      .string()
      .regex(
        /^[A-Za-z0-9_-]{32,128}$/,
        'Secret must be 32-128 URL-safe characters generated by the client.',
      ),
  })
  .strict()

export type RegisterInstallationInput = z.infer<typeof registerInstallationSchema>
